-- @@stmt thread sha256=fc1119860f1d66dbae23ec05e8f6fe55853b6271beb53994035ed6eb82788c85 scope=tenant exec=:'t',:'task',now(),NULL,'',51,NULL,'',:'r',:'pub',:'mine'
-- @@scope SELECT set_config('app.tenant_id', $1, true)
SELECT msg_id::text, received_at, env, edited_at, edited_by,
				CASE WHEN edited_at IS NULL THEN 0 ELSE COALESCE((SELECT MAX(revision)
					FROM message_revisions r WHERE r.tenant_id = messages.tenant_id AND r.msg_id = messages.msg_id), 0) END,
				is_parent, typed_by, responsible, ref_task_id::text, mirror_of::text, kind, kind_set_at, kind_set_by, moved_at, moved_by, moved_from_channel, moved_from_task::text, channel, task_id::text, parent_task_id::text
			FROM messages
			WHERE tenant_id = $1 AND task_id = $2::uuid AND expires_at > $3
				AND ($4::timestamptz IS NULL OR (received_at, msg_id::text) > ($4::timestamptz, $5::text))
				AND ($7::timestamptz IS NULL OR (received_at, msg_id::text) < ($7::timestamptz, $8::text))
				AND ((channel IS NULL AND (from_id = $9 OR to_id = $9))
			OR channel = ANY($10::text[]) OR channel = ANY($11::text[]))
			ORDER BY received_at DESC, msg_id::text DESC
			LIMIT $6
-- @@stmt flow_counts sha256=7c94ae25f00c29775e29d0b20e7bca25aadf8d3cebfecb716f7798e3347d417f scope=tenant exec=:'t',:'r',now(),:'pub',:'lobby'
-- @@scope SELECT set_config('app.tenant_id', $1, true)
WITH RECURSIVE fp(k) AS (SELECT min(x.place_key) FROM flow_events x WHERE x.tenant_id = $1 AND x.member_id = $2
			UNION ALL SELECT (SELECT min(x.place_key) FROM flow_events x WHERE x.tenant_id = $1 AND x.member_id = $2 AND x.place_key > fp.k)
			FROM fp WHERE fp.k IS NOT NULL),
		ft AS (SELECT fe.tenant_id, fe.member_id, fe.msg_id, fe.kind, fe.at, fe.expires_at FROM fp
			CROSS JOIN LATERAL (SELECT max(r.at) AS at FROM read_marks r WHERE r.tenant_id = $1 AND r.member_id = $2
				AND r.mark_key IN (fp.k, CASE WHEN fp.k LIKE 'dm:%@%' THEN regexp_replace(fp.k, '@[^@]*$', '') END)) fb
			JOIN flow_events fe ON fe.tenant_id = $1 AND fe.member_id = $2 AND fe.place_key = fp.k
				AND fe.cov_at >= coalesce(fb.at, '-infinity'::timestamptz)
			WHERE fp.k IS NOT NULL
			UNION ALL SELECT fe.tenant_id, fe.member_id, fe.msg_id, fe.kind, fe.at, fe.expires_at FROM flow_events fe
			WHERE fe.tenant_id = $1 AND fe.member_id = $2 AND (fe.place_key IS NULL OR fe.cov_at IS NULL)),
		fc AS (SELECT fe.kind, fm.channel IS NOT NULL AS in_ch,
				CASE WHEN fm.channel IS NOT NULL THEN 'ch:' || fm.channel
					WHEN coalesce(fm.from_box, '') <> '' THEN 'dm:' || fm.from_id || '@' || fm.from_box
					ELSE 'dm:' || fm.from_id END AS place_key,
				't:' || fm.task_id::text AS topic_key,
				fe.at > coalesce((SELECT s.at FROM read_marks s
				WHERE s.tenant_id = $1 AND s.member_id = $2 AND s.mark_key = 'f:seen'), '-infinity'::timestamptz) AS unseen
			FROM ft fe JOIN messages fm ON fm.tenant_id = fe.tenant_id AND fm.msg_id = fe.msg_id
			WHERE fe.expires_at > $3 AND fm.expires_at > $3 AND CASE WHEN fm.channel IS NULL THEN fe.member_id IN (fm.to_id, fm.from_id)
		WHEN fm.channel = ANY($4::text[]) THEN true
		ELSE EXISTS (SELECT 1 FROM channel_humans h WHERE h.tenant_id = fe.tenant_id AND h.channel_id = fm.channel AND h.human_id = fe.member_id)
			AND NOT EXISTS (SELECT 1 FROM channels dc WHERE dc.tenant_id = fe.tenant_id AND dc.channel_id = fm.channel AND dc.archived_at IS NOT NULL) END AND NOT (NOT (true AND NOT EXISTS (SELECT 1 FROM messages z WHERE z.tenant_id = fe.tenant_id AND z.archived_at IS NOT NULL
		AND (z.msg_id = fm.msg_id OR z.msg_id = fm.task_id
			OR (z.task_id = fm.task_id AND fm.task_id::text <> $5::text)
			OR (z.task_id = fm.parent_task_id AND fm.parent_task_id::text <> $5::text)))) OR EXISTS (SELECT 1 FROM read_marks r WHERE r.tenant_id = fe.tenant_id AND r.member_id = fe.member_id AND r.mark_key = 'f:' || fe.msg_id::text)
		OR EXISTS (SELECT 1 FROM read_marks r WHERE r.tenant_id = fe.tenant_id AND r.member_id = fe.member_id
			AND r.mark_key IN ('t:' || fm.task_id::text,
				CASE WHEN fm.channel IS NULL THEN 'dm:' || fm.from_id ELSE 'ch:' || fm.channel END,
				CASE WHEN fm.channel IS NULL THEN 'dm:' || fm.from_id || '@' || fm.from_box END)
			AND (fm.received_at, fm.msg_id::text) <= (r.at, r.msg_id))))
		SELECT count(*) FILTER (WHERE fc.unseen AND fc.kind IN ('mention', 'poke')),
			count(*) FILTER (WHERE fc.unseen AND fc.kind = 'reply'),
			count(*) FILTER (WHERE fc.unseen AND fc.kind = 'dm'),
			count(*) FILTER (WHERE fc.unseen AND fc.in_ch),
			count(*) FILTER (WHERE fc.unseen AND NOT fc.in_ch),
			count(*) FILTER (WHERE fc.kind IN ('mention', 'poke')),
			count(*) FILTER (WHERE fc.kind = 'reply'),
			count(*) FILTER (WHERE fc.kind = 'dm'),
			count(*) FILTER (WHERE fc.in_ch),
			count(*) FILTER (WHERE NOT fc.in_ch),
			(SELECT coalesce(jsonb_object_agg(k.key, k.n), '{}'::jsonb) FROM (SELECT x.key, count(*) AS n
				FROM fc f2 CROSS JOIN LATERAL (VALUES (f2.place_key), (f2.topic_key)) x(key) GROUP BY x.key) k)
		FROM fc
-- @@stmt ch_counts sha256=281950a58d20ba4abcf87248ea217f26c5ec18e1d69e9fbb1e1cf6af33536437 scope=tenant exec=:'t',now(),:'r'
-- @@scope SELECT set_config('app.tenant_id', $1, true)
WITH c AS (
			SELECT channel, count(*)::int AS n, max(received_at) AS last_at, count(DISTINCT from_id)::int AS posters,
				count(*) FILTER (WHERE $3::text IS NULL OR from_id IS DISTINCT FROM $3)::int AS others
			FROM messages WHERE tenant_id = $1 AND channel IS NOT NULL AND expires_at > $2
			GROUP BY channel)
		SELECT c.channel, c.n, c.last_at, l.msg_id, c.posters, c.others FROM c
		CROSS JOIN LATERAL (SELECT x.msg_id::text AS msg_id FROM messages x
			WHERE x.tenant_id = $1 AND x.channel = c.channel AND x.expires_at > $2 AND x.received_at = c.last_at
			ORDER BY x.msg_id::text DESC LIMIT 1) l
-- @@stmt ch_marked sha256=a97c1ff9ead4e6e7608d811dea94f0fd244cf0664f99fe2b605e9457d1653b22 scope=tenant exec=:'t',now(),'{}','{}','{}',:'r',:'lobby'
-- @@scope SELECT set_config('app.tenant_id', $1, true)
WITH pm AS (SELECT u.ch, u.at, u.id FROM unnest($3::text[], $4::timestamptz[], $5::text[]) AS u(ch, at, id)),
		sm AS (SELECT substr(mark_key, 4) AS ch, at, msg_id AS id FROM read_marks
			WHERE $6::text IS NOT NULL AND tenant_id = $1 AND member_id = $6 AND mark_key LIKE 'ch:%'),
		mk AS (SELECT DISTINCT ON (ch) ch, at, id FROM (SELECT ch, at, id FROM pm UNION ALL SELECT ch, at, id FROM sm) x ORDER BY ch, at DESC, id DESC)
		SELECT mk.ch, c.n FROM mk CROSS JOIN LATERAL (SELECT count(*)::int AS n FROM messages m
			WHERE m.tenant_id = $1 AND m.channel = mk.ch AND m.expires_at > $2
			AND m.received_at >= mk.at AND (m.received_at, m.msg_id::text) > (mk.at, mk.id)
			AND ($6::text IS NULL OR (m.from_id IS DISTINCT FROM $6 AND m.typed_by IS DISTINCT FROM $6)) AND ($6::text IS NULL OR NOT EXISTS (SELECT 1 FROM read_marks tm WHERE tm.tenant_id = $1 AND tm.member_id = $6
		AND tm.mark_key = 't:' || m.task_id::text AND (m.received_at, m.msg_id::text) <= (tm.at, tm.msg_id))) AND NOT EXISTS (SELECT 1 FROM messages z WHERE z.tenant_id = $1 AND z.archived_at IS NOT NULL
		AND (z.msg_id = m.msg_id OR z.msg_id = m.task_id
			OR (z.task_id = m.task_id AND m.task_id::text <> $7)
			OR (z.task_id = m.parent_task_id AND m.parent_task_id::text <> $7)))) c
-- @@stmt ch_hidden sha256=a7daac8cd3e24c40f79d5b4ade7bc0d09c49e8f49c833918ec37b1ca48ae55e7 scope=tenant exec=:'t',now(),'{}','{}','{}',:'r',:'lobby'
-- @@scope SELECT set_config('app.tenant_id', $1, true)
WITH RECURSIVE pm AS (SELECT u.ch, u.at, u.id FROM unnest($3::text[], $4::timestamptz[], $5::text[]) AS u(ch, at, id)),
		sm AS (SELECT substr(mark_key, 4) AS ch, at, msg_id AS id FROM read_marks
			WHERE $6::text IS NOT NULL AND tenant_id = $1 AND member_id = $6 AND mark_key LIKE 'ch:%'),
		mk AS (SELECT DISTINCT ON (ch) ch, at, id FROM (SELECT ch, at, id FROM pm UNION ALL SELECT ch, at, id FROM sm) x ORDER BY ch, at DESC, id DESC),
		cl AS (SELECT (SELECT min(channel) FROM messages WHERE tenant_id = $1 AND channel IS NOT NULL) AS ch
			UNION ALL SELECT (SELECT min(x.channel) FROM messages x WHERE x.tenant_id = $1 AND x.channel > cl.ch) FROM cl WHERE cl.ch IS NOT NULL),
		um AS (SELECT 1 FROM cl WHERE cl.ch IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mk WHERE mk.ch = cl.ch) LIMIT 1),
		z AS (SELECT msg_id, task_id FROM messages WHERE tenant_id = $1 AND archived_at IS NOT NULL AND EXISTS (SELECT 1 FROM um)),
		h AS (
			SELECT m.msg_id, m.channel, m.from_id, m.expires_at FROM z JOIN messages m ON m.tenant_id = $1 AND m.msg_id = z.msg_id AND m.channel IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mk WHERE mk.ch = m.channel)
			UNION SELECT m.msg_id, m.channel, m.from_id, m.expires_at FROM z JOIN messages m ON m.tenant_id = $1 AND m.task_id = z.msg_id AND m.channel IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mk WHERE mk.ch = m.channel)
			UNION SELECT m.msg_id, m.channel, m.from_id, m.expires_at FROM z JOIN messages m ON m.tenant_id = $1 AND m.task_id = z.task_id AND z.task_id::text <> $7 AND m.channel IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mk WHERE mk.ch = m.channel)
			UNION SELECT m.msg_id, m.channel, m.from_id, m.expires_at FROM z JOIN messages m ON m.tenant_id = $1 AND m.parent_task_id = z.task_id AND z.task_id::text <> $7 AND m.channel IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mk WHERE mk.ch = m.channel))
		SELECT h.channel, count(*)::int FROM h
		WHERE h.expires_at > $2 AND ($6::text IS NULL OR h.from_id IS DISTINCT FROM $6)
		GROUP BY h.channel
